--
-- Table structure for table `class_sessions`
--

DROP TABLE IF EXISTS `class_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `class_sessions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `enrollment_id` bigint unsigned NOT NULL,
  `recurring_schedule_id` bigint unsigned DEFAULT NULL,
  `session_date` date NOT NULL,
  `start_time` time NOT NULL,
  `duration_minutes` smallint unsigned NOT NULL DEFAULT '30',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'scheduled',
  `room` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `class_sessions_recurring_schedule_id_foreign` (`recurring_schedule_id`),
  KEY `class_sessions_session_date_status_index` (`session_date`,`status`),
  KEY `class_sessions_enrollment_id_status_index` (`enrollment_id`,`status`),
  KEY `class_sessions_session_date_index` (`session_date`),
  KEY `class_sessions_status_index` (`status`),
  KEY `class_sessions_enrollment_id_index` (`enrollment_id`),
  KEY `idx_sessions_date_enrollment_status` (`session_date`,`enrollment_id`,`status`),
  KEY `idx_sessions_date_id` (`session_date`,`id`),
  CONSTRAINT `class_sessions_enrollment_id_foreign` FOREIGN KEY (`enrollment_id`) REFERENCES `student_enrollments` (`id`) ON DELETE CASCADE,
  CONSTRAINT `class_sessions_recurring_schedule_id_foreign` FOREIGN KEY (`recurring_schedule_id`) REFERENCES `recurring_schedules` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=721 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

